sp_widget.client_script:
function($rootScope,$scope,spModal,spUtil) {
	/* widget controller */
	var c = this;
	// Use a position indicator to know which record to update
	c.ReviewPos = 0;
	c.data.selectedView=1;

	c.selectItem = function(reviewID) {  
		// Set the position indicator to the index value passed in on select
		$scope.collab_id = reviewID;
		$rootScope.reviewID = $scope.collab_id;
		$rootScope.reviewTable = 'x_snc_createnotes_note';
		$rootScope.$emit('selectRecord', [$scope.collab_id,c.data.selectedView]);
	}

	if(!c.data.selectedView) c.data.selectedView=1

	$rootScope.$on('selectedView', function(event,args) {
		c.data.action = "selectedView";
		c.data.selectedView = args;
		c.server.update({
			selectedView : args,
			action : "selectedView"
		}).then(function(r){
			c.data.action = "";
		});
	});

	c.RefreshList = function() {
		c.data.action = "selectedView";
		c.server.update({
			selectedView : c.data.selectedView,
			action : "selectedView"
		}).then(function(r){
			c.data.action = "";
		});
	}

	spUtil.recordWatch($scope, "x_snc_createnotes_note", "numberANYTHING", function(r) {
		c.server.update({
			selectedView : c.data.selectedView,
			action : "selectedView"
		}).then(function(r){
			c.data.action = "";
		});
	});

}

sp_widget.css:
h3.panel-title {
  font-size:20px;
  padding-top:5px;
}

.panel {
  box-shadow: 0 0 1rem #6f6363;
  //position: fixed;
  width: 20vw;
}

.panel-scroll {
  overflow-y: auto;
  //height: 65vh;
}

$secondary-color: #000000;
//==Backgrounds
$background-primary: #ffffff; //--now-color_background--primary
$background-secondary: #f8f6f6; //--now-color_background--secondary
$background-tertiary: #F5F0F1; //--now-color_background--tertiary

//==borders
$border-primary: #8790A1; //--now-color_border--primary
$border-secondary: #BEACB2; //--now-color_border--secondary
$border-tertiary: #E2DADD; //--now-color_border--tertiary

$brand-primary: #c31a1f; //--now-color--primary-1
$brand-danger: #E42338; //--now-color_alert--critical-2
$brand-warning: #F0E000; //--now-color_alert--warning-2
$brand-moderate: #8B6BFF; //--now-color_alert--moderate-2 NEW
$brand-low: #9698A4; //--now-color_alert--low-2 NEW
$brand-success: #51ae00; //--now-color_alert--positive-2
$brand-info: #38aaf4; //--now-color_alert--info-2

.draft {
  color:#6B7280 !important;
}

.inprogress {
  color:#F59E0B !important;
}

.onhold {
  color:#EF4444 !important;
}

.validated {
  color:#5cb85c !important;
}

.completed {
  color:#c31a1f !important;
}

.incompleted {
  color:#181B20 !important;
}

.card{
  border-radius: 10px;
  padding: 10px 10px 10px 20px;
  box-shadow: 0 0 0rem 1px #ddd;
  margin: 0px 15px 10px 15px;
  border-right: 0.5rem solid $brand-primary;

  &:hover{
    background-color: rgb(231,229,229) !important;
    //box-shadow: 0 0 1rem #a29393;
  }
}

.card-selected {
  background-color: rgb(231,229,229) !important;
}

.tag{  
  background-color: $brand-color;
  color: #ffffff;
  padding: 2px 8px;
  border-radius: 10px;
}

.avatar-container {
  margin-right:5px;
}

.avatar-display {
  display: flex;
  align-items: center;
}

.heading{
  margin-top: 1.1rem;
  margin-bottom: 1.1rem;
  color:$text-color;
}

.description{
  color: $text-muted;
  font-size: 1.4rem;
}

.btn {
  background-color: inherit;
}

.button{
  color: #ffffff;
  background-color: #ffffff;
  padding: 0.5em 1em;
  border-radius: 6px;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  border: 2px solid $secondary-color;
  box-shadow: inset 0 0 0 0 #ffffff;
  transition: ease-out 0.4s;
  cursor: pointer;

  &:hover{
    background-color: #ffffff !important;
    color: #000000;
    box-shadow: inset 400px 0 0 0 #ffffff;
  }
}
.w-100{
  width: 100%;
}

.customClass .tooltip-inner  {
  color: $fff;
  background-color: $brand-primary;
  box-shadow: 0 6px 12px rgba(0,0,0,.175);
  font-size:14px;
}

.bg{
  height: 20rem;
  background: #ffffff;
  border-radius: 10px;
  background-position: center;
  background-repeat: no-repeat;
  background-size: cover;
}

.position-absolute{
  position: absolute;
}

.panel-body {
  padding: 1.6rem 1.6rem;
}

sp_widget.link:
function link(scope, element, attrs, controller) {

	$(document).ready(function(){

		$.fn.datepicker.dates['fr'] = {
			days: ["Dimanche", "Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi"],
			daysShort: ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"],
			daysMin: ["Di", "Lu", "Ma", "Me", "Je", "Ve", "Sa"],
			months: ["Janvier", "Février", "Mars", "Avril", "Mai", "Juin", "Juillet", "Août", "Septembre", "Octobre", "Novembre", "Décembre"],
			monthsShort: ["Jan", "Fév", "Mar", "Avr", "Mai", "Juin", "Juil", "Août", "Sept", "Oct", "Nov", "Dec"],
			today: "Aujourd'hui",
			clear: "Effcer",
			format: "mm/dd/yyyy",
			titleFormat: "MM yyyy", /* Leverages same syntax as 'format' */
			weekStart: 0
		};

		setTimeout(function(){
			$('#datetimepicker').datepicker({
				format: "dd/mm/yyyy",
				startDate: "+0d",                
				endDate: "+3m",
				todayBtn: "linked",
				calendarWeeks: true,
				todayHighlight: true,
				autoclose: true,
				language: "fr"
			});
		},300);
	});

}

sp_widget.script:
(function() {
	data.filterMessage = gs.getMessage("Filter");
	data.tooltipMessage = gs.getMessage("refresh_reviews_list");

	data.reviews = [];

	var query="";
	var collabReviewGR = new GlideRecord('x_snc_createnotes_note');
	if(input) {
		if(input.selectedView==1) {
			query='collaboratorDYNAMIC90d1921e5f510100a9ad2572f2b477fe';
		}
		else if(input.selectedView==2) {
			query='collaborator.managerDYNAMIC90d1921e5f510100a9ad2572f2b477fe';
		}
	}
	else {
		query='collaboratorDYNAMIC90d1921e5f510100a9ad2572f2b477fe';
	}

	collabReviewGR.addEncodedQuery(query);
	collabReviewGR.orderByDesc('sys_created_on');
	collabReviewGR.query(query);
	while (collabReviewGR.next()) {
		var CollabReviewObj = {};
		$sp.getRecordDisplayValues(CollabReviewObj, collabReviewGR, 'collaborator,review_date,job_title, job_department, review_date , review_year, sys_id');
		CollabReviewObj.image=getAvatarPath(collabReviewGR.getValue(("collaborator")));
		CollabReviewObj.borderright = collabReviewGR.getValue("review_state");
		data.reviews.push(CollabReviewObj);
	}

	if (input) {
		if (input.action == 'newNote') {
			var newNote = new GlideRecord('x_snc_createnotes_note');
			newNote.newRecord();
			var id = newNote.insert();
			data.noteID = id;
			data.newNote = {};
			$sp.getRecordValues(data.newNote,newNote,"title,note,sys_id");
		}
		if (input.action == 'snDeleteNote') {
			var delNote = new GlideRecord('x_snc_createnotes_note');
			// The notes record should already be gone.  Just
			// making sure it no longer exists.
			if(delNote.get(input.noteID)){
				delNote.deleteRecord();
			}

		}
	}

	function getAvatarPath(userID) {
		var avatarPath = '';
		var grUser = new GlideRecord("sys_user");
		grUser.addEncodedQuery("sys_id=" + userID );
		grUser.setLimit(1);
		grUser.query();
		if (grUser.hasNext()) {
			grUser.next();
			var avatarRec = GlideAvatarFinder.getAvatarPath(grUser.getValue("sys_id")); // pass sys_id of user
			avatarPath = (avatarRec != null && avatarRec) ? encodeURI(avatarRec.toString().replace("?t=small", "")) : '';
		}

		return avatarPath;
	}

}
)();
